package com.pethop.security;
import org.springframework.boot.context.properties.ConfigurationProperties;
@ConfigurationProperties(prefix="pethop.email-verification")
public class EmailVerificationProperties { private boolean enabled; private boolean required; private boolean mailEnabled; private String frontendUrl="http://localhost:5173"; private String from="no-reply@pethop.local"; private int tokenTtlMinutes=60; public boolean isEnabled(){return enabled;} public void setEnabled(boolean v){enabled=v;} public boolean isRequired(){return required;} public void setRequired(boolean v){required=v;} public boolean isMailEnabled(){return mailEnabled;} public void setMailEnabled(boolean v){mailEnabled=v;} public String getFrontendUrl(){return frontendUrl;} public void setFrontendUrl(String v){frontendUrl=v;} public String getFrom(){return from;} public void setFrom(String v){from=v;} public int getTokenTtlMinutes(){return tokenTtlMinutes;} public void setTokenTtlMinutes(int v){tokenTtlMinutes=v;} }
